import sys
def solve(n, edges):
    from collections import defaultdict, deque
    adj = defaultdict(list)
    for u, v in edges: adj[u].append(v); adj[v].append(u)
    def get_diam(nodes):
        if not nodes: return 0
        nodes_set = set(nodes)
        def bfs(src):
            d = {src:0}; q = deque([src]); far = src
            while q:
                curr = q.popleft()
                for nb in adj[curr]:
                    if nb in nodes_set and nb not in d:
                        d[nb]=d[curr]+1; q.append(nb)
                        if d[nb] > d[far]: far = nb
            return far, d[far]
        f1, _ = bfs(list(nodes)[0])
        f2, dist = bfs(f1)
        return dist
    def get_comp(start, skip_edge):
        res = []; q = deque([start]); vis = {start}
        while q: 
            u = q.popleft(); res.append(u)
            for v in adj[u]:
                if v not in vis and (u, v) != skip_edge and (v, u) != skip_edge:
                    vis.add(v); q.append(v)
        return res
    ans = float('inf')
    for u, v in edges:
        s1 = get_comp(u, (u, v))
        s2 = get_comp(v, (u, v))
        ans = min(ans, max(get_diam(s1), get_diam(s2)))
    return str(ans)


if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data: exit()
    n = int(data[0])
    edges = []
    for i in range(n-1): edges.append((int(data[1+i*2]), int(data[2+i*2])))
    print(solve(n, edges))

